CREATE OR REPLACE FUNCTION public.support_training_replay_review(p_id uuid,p_class_ok boolean,p_correct_category text,p_reply_ok boolean,p_comment text,p_ideal_reply text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'forbidden'; END IF; IF p_correct_category IS NOT NULL AND p_correct_category NOT IN ('troca','devolucao','troca_ou_devolucao_ambiguo','rastreio','outro_suporte','venda','nada') THEN RAISE EXCEPTION 'invalid category'; END IF; IF length(coalesce(p_comment,''))>2000 OR length(coalesce(p_ideal_reply,''))>2000 THEN RAISE EXCEPTION 'too long'; END IF; UPDATE public.support_training_items SET replay_result=jsonb_set(replay_result,'{review}',jsonb_build_object('class_ok',p_class_ok,'correct_category',p_correct_category,'reply_ok',p_reply_ok,'comment',p_comment,'ideal_reply',p_ideal_reply,'by',auth.uid(),'at',now())) WHERE id=p_id AND replay_status='ok'; END $$;
REVOKE ALL ON FUNCTION public.support_training_replay_review(uuid,boolean,text,boolean,text,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.support_training_replay_review(uuid,boolean,text,boolean,text,text) TO authenticated;
DO $$ DECLARE d text; BEGIN SELECT pg_get_functiondef('public.support_training_list(uuid,text,boolean,integer,integer)'::regprocedure) INTO d; d:=replace(d,'reviewed_at IS NULL','CASE WHEN replay_result IS NOT NULL THEN replay_result->''review''->>''at'' IS NULL ELSE reviewed_at IS NULL END'); EXECUTE d; END $$;